    public static ReadOnlySpan<LanguageOption> Languages => Options;

    public static string Normalize(string? code) =>
        Options.Any(option => string.Equals(option.Code, code, StringComparison.OrdinalIgnoreCase))
            ? Options.First(option => string.Equals(option.Code, code, StringComparison.OrdinalIgnoreCase)).Code
            : "en";

    public static string LanguageName(string code) =>
        Options.FirstOrDefault(option => option.Code == Normalize(code))?.Name ?? "English";

    public static string T(string languageCode, string key)
    {
        string code = Normalize(languageCode);
        if (SupplementalTexts.TryGetValue(code, out var additional) && additional.TryGetValue(key, out var translated))
            return translated;
        if (Texts.TryGetValue(code, out Dictionary<string, string>? language) &&
            language.TryGetValue(key, out string? value))
        {
            return value;
        }
        return Texts["en"].TryGetValue(key, out string? english) ? english : key;
    }

