    private static Dictionary<string, string> Quick(string home, string profiles, string options,
        string playMode, string launch, string profilesHeading, string language, string save, string cancel)
    {
        Dictionary<string, string> copy = English();
        copy["Nav.Home"] = home;
        copy["Nav.Profiles"] = profiles;
        copy["Nav.Options"] = options;
        copy["Home.ModeHeading"] = playMode;
        copy["Home.Launch"] = launch;
        copy["Profiles.Heading"] = profilesHeading;
        copy["Options.Language"] = language;
        copy["Options.Save"] = save;
        copy["Options.Cancel"] = cancel;
        return copy;
    }

